"""Interactive display of the connected executable stack and source evidence."""
def page(as_of=None):
    from .graph_workbench import enhance
    from .workspace_shell import enhance as workspace
    return workspace(enhance(HTML,as_of))

HTML=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agere · Intelligence engine</title>
<style>
:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif;background:#071017;color:#eef6f5;--line:#24404b;--green:#abf5d4;--muted:#9aafb7}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 15% 10%,#173c3b80,transparent 50%),#071017}main{max-width:1440px;margin:auto;padding:36px 5vw 80px}nav{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:24px;font-size:13px}a{color:var(--green);text-decoration:none}.brand{letter-spacing:5px;font-weight:600}.tag{color:var(--muted)}h1{font-size:clamp(38px,6vw,78px);line-height:1.03;font-weight:450;letter-spacing:-3px;max-width:960px;margin:42px 0 22px}h1 em{font-style:normal;color:var(--green)}p{color:var(--muted);line-height:1.65;max-width:900px}.flow{display:grid;grid-template-columns:repeat(4,1fr);margin:36px 0;border:1px solid var(--line);border-radius:15px;overflow:hidden}.stage{padding:24px;border-right:1px solid var(--line);position:relative;min-height:190px;background:#10242d80}.stage:last-child{border:0}.stage small{font:11px monospace;color:var(--green);letter-spacing:2px}.stage h2{font-size:23px;font-weight:450;margin:20px 0 12px}.stage p{font-size:12px;line-height:1.7;margin:0}.stage:after{content:'';position:absolute;bottom:0;left:0;width:80px;height:2px;background:var(--green);animation:pass 5s linear infinite;animation-delay:var(--delay)}@keyframes pass{0%{transform:translateX(-100px);opacity:0}20%{opacity:1}100%{transform:translateX(380px);opacity:0}}.metrics{display:flex;flex-wrap:wrap;gap:28px;margin:26px 0}.metric b{font-size:25px;display:block;font-weight:450}.metric span{font:11px monospace;color:var(--muted)}.lab{border:1px solid #456363;padding:26px;border-radius:14px;background:#10252c}label{font-size:13px;color:#c8dcdf}textarea,input,select{background:#0a1921;color:#f2faf9;border:1px solid #385562;border-radius:7px;font:16px/1.5 system-ui;padding:15px;width:100%}textarea{min-height:110px;margin:12px 0}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}button{font:13px system-ui;cursor:pointer;padding:12px 18px;border-radius:7px;border:1px solid #3b6565;background:#18353a;color:#dff6ed}button.primary{background:var(--green);color:#0b2920;border-color:var(--green)}button:disabled{opacity:.5;cursor:wait}.chips{display:flex;gap:9px;flex-wrap:wrap;margin:16px 0 5px}.chip{font-size:12px;padding:9px 13px}.status{min-height:36px;color:var(--green);font:13px/1.7 monospace;margin:18px 0}.results{display:grid;gap:20px}article{background:#10232b;border:1px solid var(--line);border-radius:12px;padding:24px}article h2{font-weight:450;margin:0 0 12px}.pill{display:inline-block;font:11px monospace;padding:6px 10px;border:1px solid #557466;border-radius:25px;color:var(--green);margin-right:8px}.missing{color:#efd6a4;border-left:2px solid #ba9562;padding-left:16px}.source{border-top:1px solid var(--line);margin-top:18px;padding-top:18px}.source h3{font:13px monospace;color:var(--green)}blockquote{margin:16px 0;padding-left:18px;border-left:2px solid #6c9b98;font:14px/1.8 system-ui;color:#d2e5e7;white-space:pre-wrap;overflow-wrap:anywhere}summary{cursor:pointer;font-size:12px;color:#a6c7cd}pre{font:12px/1.7 monospace;background:#081a22;padding:15px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:440px;overflow:auto}.meta{font-size:12px;color:#91aeb5}.patient{display:grid;grid-template-columns:200px 1fr;gap:20px;border-top:1px solid var(--line);padding-top:18px;margin-top:18px}.patient h3{font:12px monospace;color:var(--green);overflow-wrap:anywhere}.chart{height:105px;width:100%;max-width:500px}.review-controls{display:flex;gap:9px}.notice{font-size:12px;max-width:none;margin:18px 0}.legend{display:flex;gap:12px;flex-wrap:wrap}.legend span{font-size:11px;color:#9ebcbf}details{margin-top:16px}.warn{color:#efd6a4}.sub{margin:12px 0}.steps{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}#patient{width:220px;font:12px monospace;padding:12px}.operator{padding:10px 15px}.footer{margin-top:40px;border-top:1px solid var(--line);padding-top:20px;font-size:12px}@media(max-width:800px){.flow{grid-template-columns:1fr 1fr}.stage{border-bottom:1px solid var(--line)}.patient{grid-template-columns:1fr}.flow h2{font-size:19px}h1{letter-spacing:-1px}main{padding:25px 20px}}@media(prefers-reduced-motion:reduce){.stage:after{animation:none}}
</style><main><nav><span class="brand">AGERE</span><span class="tag">THE CONNECTED INTELLIGENCE ENGINE · SYNTHETIC WORKSPACE</span><a href="/learn">Source learning ↗</a><a href="/programs">Program workspace ↗</a><a href="/explore">Evidence predicates ↗</a></nav>
<h1>The data arrives in pieces.<br><em>The question gets a path.</em></h1><p>Search the notes and discrete fields together. Follow the evidence through the models and calculations that can use it. See precisely where a result ends and a missing input begins.</p>
<div class="flow"><div class="stage" style="--delay:0s"><small>01 / RECONCILE</small><h2>Make sources legible.</h2><p>Patient identity · arrival vs. event time<br>Corrections · structured adapters<br>Received free text · OCR</p></div><div class="stage" style="--delay:1s"><small>02 / RETRIEVE</small><h2>Find the signal.</h2><p>Local MiniLM vectors + BM25<br>Reciprocal-rank fusion<br>BGE relevance reranking · source diversity</p></div><div class="stage" style="--delay:2s"><small>03 / REASON</small><h2>Use the right engine.</h2><p>Local plan → compact model → specialist → frontier<br>Kidney trends · medication evidence<br>Source coverage · ADT patterns</p></div><div class="stage" style="--delay:3s"><small>04 / REVEAL</small><h2>Show what supports it.</h2><p>Source dates · exact text spans<br>Optional Jev / Perplexity review<br>Open requirements · cached receipts</p></div></div>
<div class="metrics" id="metrics"></div>
<style>.scope-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:20px 0}.scope-grid label{display:block}.scope-grid input,.scope-grid select{display:block;margin-top:7px;font-size:13px;padding:10px}.scope-preview{display:flex;gap:12px;flex-wrap:wrap}.event{border-left:1px solid #497d72;padding:5px 0 5px 18px;margin:10px 0}.scope-grid~table{width:100%}table{width:100%;border-collapse:collapse;font:13px/1.7 monospace}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}.event b{color:var(--green);font:12px monospace}@media(max-width:800px){.scope-grid{grid-template-columns:1fr 1fr}}</style>
<section class="lab"><label for="question">A healthcare data question</label><textarea id="question" maxlength="1500">Whose kidney function is declining, and what data is missing to understand their risk?</textarea><div class="controls"><button class="primary" id="search">Search evidence locally</button><button id="plan">Plan economically and calculate</button><input id="patient" aria-label="Optional patient ID" placeholder="Optional synthetic patient ID"></div><div class="chips"><button class="chip" data-question="Where do the notes document outside nephrology care or requests for records?">Outside care</button><button class="chip" data-question="Which heart failure records distinguish a medication order from taking it, or a treatment hold?">Orders vs. use</button><button class="chip" data-question="Which records describe financial difficulty paying for medicines?">Affordability</button><button class="chip" data-question="Which records describe admission or readmission context?">Admission context</button></div><div class="scope-grid"><label>Roster coverage<select id="coverage"><option value="">All observed coverage types</option></select></label><label>Region<select id="region"><option value="">All regions</option></select></label><label>Minimum age at cutoff<input type="number" id="min-age" min="0" max="130" placeholder="Any age"></label><label>Documented diagnosis code prefix<input id="code-prefix" maxlength="20" placeholder="Example: N18"></label><label>Encounter organization<select id="organization"><option value="">All encounter organizations</option></select></label><label>Date basis<select id="date-basis"><option value="all_observed">All observed records</option><option value="clinical">Explicit clinical date</option><option value="source_event">Source event date</option><option value="arrival">Arrival date</option></select></label><label>Start date<input type="date" id="date-start"></label><label>End date<input type="date" id="date-end"></label></div><div class="scope-preview"><button id="preview-cohort">Inspect selected population locally</button><span class="meta">Diagnosis filters match documented codes. Organization filters match encounters; they do not establish attribution.</span></div><div class="chips"><button class="operator" data-op="clinical_timeline">Open clinical timelines</button><button class="operator" data-op="source_volume_monitor">Analyze source-volume changes</button><button class="operator" data-op="claims_runout">Calculate claims runout</button><button class="operator" data-op="heart_failure_review">Open HF evidence panels</button><button class="operator" data-op="kidney_trajectory" data-view="declining">Calculate renal patterns</button><button class="operator" data-op="kidney_trajectory" data-view="missing_inputs">Find missing renal inputs</button><button class="operator" data-op="medication_evidence">Reconcile beta-blocker evidence</button><button class="operator" data-op="source_completeness">Inspect source completeness</button><button class="operator" data-op="warehouse_interpretation">Reconcile warehouse source meanings</button><button class="operator" data-op="program_rule_review">Run versioned program rules</button></div><p class="notice">All records are synthetic. Search returns ranked examples. Calculations describe observed data. Question planning uses local compilation, compact retrieval and typed routing before frontier escalation; patient review uses the selected typed API. Missing documentation leaves care status unresolved.</p></section>
<div id="status" class="status" role="status" aria-live="polite"></div><section id="results" class="results" aria-live="polite"></section><div class="footer">Every model has a bounded role. Relevance is not clinical truth. Persistent review and program work are available in the program workspace. External action execution remains a future layer.</div></main>
<script>
const $=id=>document.getElementById(id),N=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};let seq=0,live=false;
function details(title,value){const d=N('details');d.append(N('summary',title),N('pre',JSON.stringify(value,null,2)));return d}
function chart(series){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 500 105');svg.classList.add('chart');svg.setAttribute('role','img');svg.setAttribute('aria-label','Observed eGFR by source date');if(series.length<2)return svg;const ys=series.map(x=>x.value),lo=Math.min(...ys)-3,hi=Math.max(...ys)+3,ds=series.map(x=>Date.parse(x.date)),span=ds.at(-1)-ds[0]||1;const path=document.createElementNS(svg.namespaceURI,'polyline');path.setAttribute('points',series.map((r,i)=>`${10+480*(ds[i]-ds[0])/span},${95-80*(r.value-lo)/(hi-lo)}`).join(' '));path.setAttribute('fill','none');path.setAttribute('stroke','#abf5d4');path.setAttribute('stroke-width','2');svg.append(path);series.forEach((r,i)=>{const c=document.createElementNS(svg.namespaceURI,'circle');c.setAttribute('cx',10+480*(ds[i]-ds[0])/span);c.setAttribute('cy',95-80*(r.value-lo)/(hi-lo));c.setAttribute('r','3');c.setAttribute('fill','#abf5d4');const t=document.createElementNS(svg.namespaceURI,'title');t.textContent=r.date+' · '+r.value+' '+r.unit;c.append(t);svg.append(c)});return svg}
function retrieval(d){const a=N('article');a.append(N('h2','Ranked source evidence'),N('p',d.method,'meta'),N('p',d.scope,'meta'));for(const row of d.evidence){const s=row.source,b=N('div',undefined,'source');b.append(N('h3',s.patient_id+' · '+s.source_table+' / '+s.field),N('p','Source event '+s.event_date+' · arrived '+s.available_date+' · '+s.kind,'meta'),N('blockquote',row.text));const controls=N('div',undefined,'review-controls');for(const provider of ['perplexity','jev']){const button=N('button','Review patient evidence with '+(provider==='jev'?'Jev':'Perplexity'));button.disabled=!live;button.onclick=()=>run('/api/stack/review',{question:$('question').value,patient:s.patient_id,provider});controls.append(button)}b.append(controls,details('Inspect exact source and relevance scores',row));a.append(b)}if(!d.evidence.length)a.append(N('p','No selected passages. This does not establish absence of care.'));$('results').append(a)}
function cohortView(d){const a=N('article');const c=d.counts;a.append(N('h2','The selected population'),N('span',c.matched.toLocaleString()+' matched','pill'),N('span',c.unknown.toLocaleString()+' unresolved','pill'),N('p',c.evaluated.toLocaleString()+' synthetic patients evaluated · '+c.not_matched.toLocaleString()+' did not match the observed predicates.','meta'),N('p',d.scope,'meta'));if(c.unknown)a.append(N('p','Unresolved patients are reported separately and are not silently included or excluded as clinical negatives.','missing'));a.append(details('Cohort predicates, source evidence and unresolved examples',d));$('results').append(a)}
function scope(){const all=[],any=[];for(const field of ['coverage','region'])if($(field).value)all.push({kind:'patient',field,op:'eq',value:$(field).value});if($('min-age').value!=='')all.push({kind:'patient',field:'age',op:'ge',value:Number($('min-age').value)});const w={basis:$('date-basis').value,start:$('date-start').value,end:$('date-end').value};if(w.basis==='all_observed'&&(w.start||w.end))throw Error('Choose a date basis for the supplied date range.');const prefix=$('code-prefix').value.trim();if(prefix)for(const [stream,field] of [['medical_claims','dx'],['problem_lists','problem_code']])any.push({kind:'record',stream,conditions:[{field,op:'prefix',value:prefix}],window:w});if($('organization').value)all.push({kind:'record',stream:'encounters',conditions:[{field:'organization_id',op:'eq',value:$('organization').value}],window:w});return {cohort:{all,any,exclude:[]},analysis_window:w}}
function local(endpoint,body){try{const filters=scope();if(endpoint==='/api/stack/cohort')delete filters.analysis_window;return run(endpoint,{...body,...filters})}catch(e){$('status').textContent=e.message}}
function scopedQuestion(){scope();let q=$('question').value;for(const field of ['coverage','region'])if($(field).value)q+=' Only roster '+field+' "'+$(field).value+'".';if($('min-age').value)q+=' Only patients age '+$('min-age').value+' or older at the snapshot cutoff.';if($('code-prefix').value.trim())q+=' Only patients with observed diagnosis code prefix "'+$('code-prefix').value.trim()+'" in claims or problem lists.';if($('organization').value)q+=' Only patients with an encounter record at organization "'+$('organization').value+'".';if($('date-basis').value!=='all_observed')q+=' Analysis date basis: '+$('date-basis').value+', start '+($('date-start').value||'beginning of observed data')+', end '+($('date-end').value||'snapshot cutoff')+'.';if($('patient').value.trim())q+=' For patient '+$('patient').value.trim()+'.';return q}
function analytic(d){const a=N('article');a.append(N('h2',d.operator.replaceAll('_',' ')),N('span',d.summary.patients.toLocaleString()+' synthetic patients','pill'),N('p',d.requirements.limits,'meta'));if(d.summary.with_source_disagreements!==undefined)a.append(N('p',d.summary.with_source_disagreements+' patients with source disagreements · '+d.summary.with_excluded_dispense_observations+' with excluded dispense observations','warn'));if(d.summary.with_order_records!==undefined)a.append(N('p',`${d.summary.with_order_records} with order records · ${d.summary.explicit_dispense_date_supply_documented} with explicit dispense-date supply documentation · ${d.summary.with_transaction_issues} with rejected/reversed transaction records`));if(d.calculation){if(d.operator==='source_volume_monitor'){for(const source of d.calculation.sources){const panel=N('div',undefined,'source');panel.append(N('h3',source.source+' · '+source.status.replaceAll('_',' ')));if(source.months){const series=source.months.map((m,i)=>({date:m+'-01',value:source.record_counts[i],unit:'observed source records'}));const graph=chart(series);graph.setAttribute('aria-label','Monthly observed '+source.source+' record volume');panel.append(graph,N('p',source.input_record_count+' contributing records · '+(source.points||[]).filter(x=>x.investigate_source_change).length+' months flagged for source investigation','meta'),N('p',source.reference_basis,'meta'))}a.append(panel)}}else if(d.operator==='claims_runout'){const table=N('table');const head=N('tr');['Service month','Payment lag (months)','Observed payer-paid dollars'].forEach(x=>head.append(N('th',x)));table.append(head);for(const c of d.calculation.cells){const row=N('tr');[c.service_month,c.payment_lag_months,c.paid_usd.toLocaleString(undefined,{style:'currency',currency:'USD'})].forEach(x=>row.append(N('td',x)));table.append(row)}a.append(table)}a.append(details('Mathematical calculation and source-input receipt',d.calculation))}if(d.date_scope)a.append(N('p',d.date_scope.records_selected+' records inside the analysis scope · '+d.date_scope.records_with_unknown_date+' with unresolved window membership · '+d.date_scope.records_outside_window+' outside the window.','meta'));for(const p of d.patients){const b=N('div',undefined,'patient'),body=N('div');b.append(N('h3',p.patient_id),body);if(d.operator==='kidney_trajectory'){const e=p.measurements.egfr;body.append(N('span',p.egfr_pattern.replaceAll('_',' '),'pill'),chart(e.series));if(e.trajectory.status==='computed')body.append(N('p','Theil–Sen slope '+e.trajectory.slope_per_year.toFixed(2)+' '+(e.series[0]?.unit||'')+' per year · '+e.trajectory.points+' distinct source dates','meta'));body.append(N('p','Missing inputs: '+p.missing_inputs.join(', ').replaceAll('_',' '),'missing'),N('p','Acute vs. chronic: '+p.acute_vs_chronic.replaceAll('_',' '),'meta'))}else if(d.operator==='clinical_timeline'){for(const e of p.dated_events.slice(-12)){const t=N('div',undefined,'event');t.append(N('b',e.clinical_date),N('p',e.source.source_table+' · '+e.source.record_id,'meta'));body.append(t)}body.append(N('p',p.summary.unresolved_or_future_events+' events have unresolved clinical dates or window membership.','missing'))}else if(p.workflow){body.append(N('span',p.workflow.status.replaceAll('_',' '),'pill'));if(p.workflow.medications){for(const med of p.workflow.medications)body.append(N('p',med.drug_class.toUpperCase()+' · '+med.evidence_state.replaceAll('_',' ')+' · actual use / maximum tolerated dose unresolved','meta'))}for(const need of p.workflow.missing_information)body.append(N('p',need,'missing'))}else if(d.operator==='warehouse_interpretation'){body.append(N('p',Object.entries(p.relation_counts).map(([k,v])=>k.replaceAll('_',' ')+': '+v).join(' · ')),N('p',Object.entries(p.state_counts).map(([k,v])=>k.replaceAll('_',' ')+': '+v).join(' · '),'meta'));const groups=new Map();for(const step of p.evidence_acquisition_steps){const key=JSON.stringify([step.action,step.relation]);if(!groups.has(key))groups.set(key,{...step,count:0});groups.get(key).count++}for(const step of Array.from(groups.values()).slice(0,6))body.append(N('p',step.action+' · '+step.relation.replaceAll('_',' ')+' · '+step.count+' source '+(step.count===1?'account':'accounts'),'missing'));body.append(N('p','Source statements preserve separate orders, pharmacy fulfilment, reported use, care confirmation and document validity.','meta'))}else if(d.operator==='source_completeness'){body.append(N('p',Object.entries(p.records_by_source).map(([k,v])=>k+': '+v).join(' · ')),N('p',p.coverage_status,'missing'))}else if(d.operator==='medication_evidence')body.append(N('p',p.supply.status.replaceAll('_',' ')),N('p',p.supply.supplies.length+' current supply intervals · '+p.supply.historical_supplies.length+' historical intervals · '+p.supply.source_disagreements.length+' source disagreements · '+p.supply.excluded_dispense_observations.length+' excluded dispense observations','meta'),N('p','Maximum tolerated dose and actual use remain unresolved.','missing'));body.append(details('Open calculation, inputs and source evidence',p));a.append(b)}a.append(details('Operator requirements and result receipt',{summary:d.summary,snapshot:d.snapshot,requirements:d.requirements}));$('results').append(a)}
function render(d){if(d.cohort)cohortView(d.cohort);else if(d.schema==='observed-cohort/1')cohortView(d);if(d.retrieval)retrieval(d.retrieval);if(d.plan){const a=N('article');a.append(N('h2','The executable interpretation'),N('p',d.plan.interpretation),N('span',d.plan.coverage.replaceAll('_',' '),'pill'));const stages=N('div',undefined,'steps');d.plan.steps.forEach(s=>stages.append(N('span',s.operation.replaceAll('_',' '),'pill')));a.append(stages);if(d.plan.unmet_requirements.length){a.append(N('p','Still needed to answer the entire question','warn'));const list=N('ul',undefined,'missing');d.plan.unmet_requirements.forEach(x=>list.append(N('li',x)));a.append(list)}a.append(details('Typed plan and model usage receipt',{plan:d.plan,planner_receipt:d.planner_receipt}));$('results').append(a)}if(d.results)d.results.forEach(x=>x.step.operation==='evidence_search'?retrieval(x.result):analytic(x.result));if(d.operator)analytic(d);if(d.model_proposal){const a=N('article');a.append(N('h2','Patient-scoped model proposal'),N('p','Inspect support and uncertainty before drawing a clinical conclusion.','meta'),details('Typed model answer and API receipt',d.model_proposal));$('results').append(a)}}
async function run(endpoint,body){const id=++seq;$('results').replaceChildren();$('status').textContent='Following the question through the selected stack layers…';try{const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(id!==seq)return;if(!r.ok)throw Error(d.error||'Request failed');render(d);$('status').textContent=`Completed · ${d.new_paid_api_calls??d.model_proposal?.new_paid_api_calls??'see receipt'} new paid API calls · source evidence retained.`}catch(e){if(id===seq)$('status').textContent=e.message}}
$('search').onclick=()=>local('/api/stack/search',{question:$('question').value,patient:$('patient').value.trim()});$('preview-cohort').onclick=()=>local('/api/stack/cohort',{patient:$('patient').value.trim()});$('plan').onclick=()=>{try{run('/api/stack/ask',{question:scopedQuestion(),live:true})}catch(e){$('status').textContent=e.message}};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{$('question').value=b.dataset.question;local('/api/stack/search',{question:b.dataset.question,patient:$('patient').value.trim()})});document.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>local('/api/stack/operator',{operator:b.dataset.op,view:b.dataset.view||'all',patient:$('patient').value.trim(),drug_class:b.dataset.op==='medication_evidence'?'bb':null}));
fetch('/api/stack/meta').then(r=>r.json()).then(d=>{live=d.allow_live;$('plan').disabled=false;const choices=d.observed_values||{};for(const field of ['coverage','region'])for(const v of Object.keys(choices.roster?.[field]||{}).sort()){const o=N('option',v);o.value=v;$(field).append(o)}for(const v of Object.keys(choices.encounter_organizations||{}).sort()){const o=N('option',v);o.value=v;$('organization').append(o)}const vals=[['Synthetic patients',d.retrieval.patients],['Visible source records',d.retrieval.visible_records],['Searchable passages',d.retrieval.passages],['Embedded passage texts',d.retrieval.dense_passage_texts??d.retrieval.unique_passage_texts]];vals.forEach(([label,value])=>{const e=N('div',undefined,'metric');e.append(N('b',value.toLocaleString()),N('span',label));$('metrics').append(e)});const dataset=N('article');dataset.id='dataset-provenance';dataset.append(N('h2','Connected healthcare warehouse'),N('p',(d.retrieval.snapshot.source_dataset?.source||'Historical integration snapshot')+' · synthetic cutoff '+d.retrieval.snapshot.as_of),N('p',d.retrieval.snapshot.source_dataset?'Original patient IDs preserved. Unknown event dates remain unknown. Generator private state is excluded.':'Source identity is recorded in the retrieval receipt.','meta'));$('metrics').after(dataset);if(seq===0)$('status').textContent=live?'Local retrieval and analytic operators ready. Economical planning and typed reviewers connected.':'Local layers ready. This server has hosted inference disabled.'}).catch(e=>{if(seq===0)$('status').textContent=e.message});
</script></html>'''
